public static boolean twoSum(Queue<Integer> q, int x) {
    int n = size(q);
    // כל איבר בתורו יוצא מהתור, ומשווים אותו לכל שאר האיברים (סיבוב שלם של התור)
    for (int i = 0; i < n; i++) {
        int a = q.remove();
        for (int j = 0; j < n - 1; j++) {
            int b = q.remove();
            if (a + b == x) {
                return true;
            }
            q.insert(b);
        }
        q.insert(a);
    }
    return false;
}

