public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

// הפעולה הנתונה בשאלה: מספר האיברים בתור q, בלי לשנות את התור
public static int size(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int count = 0;
    while (!q.isEmpty()) {
        temp.insert(q.remove());
        count++;
    }
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return count;
}

// תור עם הערכים לפי הסדר (הראשון — בראש התור)
public static Queue<Integer> build(int[] values) {
    Queue<Integer> q = new Queue<Integer>();
    for (int i = 0; i < values.length; i++) {
        q.insert(values[i]);
    }
    return q;
}

exercise.mainCode:
System.out.println("סעיף א, בדיקה 1 (הדוגמה, x = 10): " + check(twoSum(build(new int[] { 5, 4, 1, 4, 3, 15, 9 }), 10), true));
System.out.println("סעיף א, בדיקה 2 (הדוגמה, x = 100 — אין זוג כזה): " + check(twoSum(build(new int[] { 5, 4, 1, 4, 3, 15, 9 }), 100), false));
System.out.println("סעיף א, בדיקה 3 (אותו איבר לא נספר פעמיים): " + check(twoSum(build(new int[] { 4, 1, 3 }), 8), false));
System.out.println("סעיף א, בדיקה 4 (שני איברים שווים): " + check(twoSum(build(new int[] { 4, 1, 4 }), 8), true));
System.out.println("סעיף א, בדיקה 5 (שני איברים בתור): " + check(twoSum(build(new int[] { 6, 4 }), 10), true));
System.out.println("סעיף א, בדיקה 6 (שני איברים בתור, בלי זוג): " + check(twoSum(build(new int[] { 6, 4 }), 12), false));

